    lamInsertionOrbit.add(RAAN_UNCERTAINTY_DEG: RAAN_UNCERTAINTY_DEG, &fbb)
    lamInsertionOrbit.add(ARGUMENT_OF_LATITUDE_UNCERTAINTY_DEG: ARGUMENT_OF_LATITUDE_UNCERTAINTY_DEG, &fbb)
