    try _v.visit(field: VT.RAAN_DEG, fieldName: "RAAN_DEG", required: false, type: Double.self)
    try _v.visit(field: VT.ARGUMENT_OF_PERIAPSIS_DEG, fieldName: "ARGUMENT_OF_PERIAPSIS_DEG", required: false, type: Double.self)
